/* Generated by `helix system machines` from machine.ts beside it. Do not
   edit: change the machine and run it again. */
import { type RovingContext, followsFocus, placed, selects, toFirst, toLast, toNext, toPrevious } from './machine.js'

export type { RovingContext } from './machine.js'

/** The name machine.ts exports the machine as. */
export const NAME = 'rovingFocus'

/** The state `away`. */
export const STATE_AWAY = 0
/** The state `placed`. */
export const STATE_PLACED = 1
/** The state `unplaced`. */
export const STATE_UNPLACED = 2
/** Each state's name, by its number. */
export const STATES = ['away', 'placed', 'unplaced'] as const

/** Each state as the machine writes it, by the number a deadline names its owner by. */
export const NODES = ['away', 'placed', 'unplaced'] as const

/** The event `NEXT`. */
export const EVENT_NEXT = 0
/** The event `PREVIOUS`. */
export const EVENT_PREVIOUS = 1
/** The event `FIRST`. */
export const EVENT_FIRST = 2
/** The event `LAST`. */
export const EVENT_LAST = 3
/** Each event's name, by its number. */
export const EVENTS = ['NEXT', 'PREVIOUS', 'FIRST', 'LAST'] as const

/** The effect `focus`. */
export const EFFECT_FOCUS = 0
/** The effect `select`. */
export const EFFECT_SELECT = 1
/** Each effect's name, by its number. */
export const EFFECTS = ['focus', 'select'] as const

/** Each request event's name, by its number. */
export const ASKS = [] as const

/** A literal an effect is given. */
export type Argument = Readonly<Record<string, boolean | number | string>>

/** An effect the host performs: its number, and its argument where it has one. */
export type Effect = readonly [effect: number, argument?: Argument]

/** A move: the state it leaves the machine in, the context after it, and the effects it runs, in order. */
export interface Move {
  readonly context: RovingContext
  readonly effects: readonly Effect[]
  readonly state: number
}

/** A request: the events the host asks with first, in order, and the move for each outcome. */
export interface Asking {
  readonly accept: Move
  readonly ask: readonly number[]
  readonly refuse: Move
}

/** The state the machine is in, read from its context. */
export const start = (context: RovingContext): number =>
  placed(context) ? STATE_PLACED : followsFocus(context) ? STATE_AWAY : STATE_UNPLACED

/** The effects of starting in a state, as a host that mounts the machine runs them. */
export const entering = (_state: number): readonly Effect[] => []

/** What `placed` does with each event. */
const inPlaced = (context: RovingContext, event: number, _input: undefined): Move | Asking | undefined => {
  switch (event) {
    case EVENT_NEXT:
      return selects(context) ? { context: toNext(context), effects: [[EFFECT_FOCUS], [EFFECT_SELECT]], state: STATE_PLACED } : { context: toNext(context), effects: [[EFFECT_FOCUS]], state: STATE_PLACED }
    case EVENT_PREVIOUS:
      return selects(context) ? { context: toPrevious(context), effects: [[EFFECT_FOCUS], [EFFECT_SELECT]], state: STATE_PLACED } : { context: toPrevious(context), effects: [[EFFECT_FOCUS]], state: STATE_PLACED }
    case EVENT_FIRST:
      return selects(context) ? { context: toFirst(context), effects: [[EFFECT_FOCUS], [EFFECT_SELECT]], state: STATE_PLACED } : { context: toFirst(context), effects: [[EFFECT_FOCUS]], state: STATE_PLACED }
    case EVENT_LAST:
      return selects(context) ? { context: toLast(context), effects: [[EFFECT_FOCUS], [EFFECT_SELECT]], state: STATE_PLACED } : { context: toLast(context), effects: [[EFFECT_FOCUS]], state: STATE_PLACED }
  }
  return undefined
}

/** What `unplaced` does with each event. */
const inUnplaced = (context: RovingContext, event: number, _input: undefined): Move | Asking | undefined => {
  switch (event) {
    case EVENT_NEXT:
      return selects(context) ? { context: toFirst(context), effects: [[EFFECT_FOCUS], [EFFECT_SELECT]], state: STATE_PLACED } : { context: toFirst(context), effects: [[EFFECT_FOCUS]], state: STATE_PLACED }
    case EVENT_PREVIOUS:
      return selects(context) ? { context: toLast(context), effects: [[EFFECT_FOCUS], [EFFECT_SELECT]], state: STATE_PLACED } : { context: toLast(context), effects: [[EFFECT_FOCUS]], state: STATE_PLACED }
    case EVENT_FIRST:
      return selects(context) ? { context: toFirst(context), effects: [[EFFECT_FOCUS], [EFFECT_SELECT]], state: STATE_PLACED } : { context: toFirst(context), effects: [[EFFECT_FOCUS]], state: STATE_PLACED }
    case EVENT_LAST:
      return selects(context) ? { context: toLast(context), effects: [[EFFECT_FOCUS], [EFFECT_SELECT]], state: STATE_PLACED } : { context: toLast(context), effects: [[EFFECT_FOCUS]], state: STATE_PLACED }
  }
  return undefined
}

/**
 * What an event does in a state: a move, a request, or `undefined` where the
 * state ignores it.
 */
export const step = (state: number, context: RovingContext, event: number, input: undefined): Move | Asking | undefined => {
  switch (state) {
    case STATE_PLACED:
      return inPlaced(context, event, input)
    case STATE_UNPLACED:
      return inUnplaced(context, event, input)
  }
  return undefined
}

/**
 * The move a state's deadline makes when it ends, or `undefined` where the
 * state `owner` names is not active in `state`.
 */
export const expire = (_state: number, _context: RovingContext, _owner: number): Move | undefined =>
  undefined

/** The move the machine's cancel makes from a state, where it has one. */
export const cancel = (_state: number, _context: RovingContext): Move | undefined => undefined

/** The custom states a host records while the machine is in `state`. */
export const mark = (_state: number): readonly string[] => []
